"""Shared formatting and CLI of the tune data generators: PSID in, C header out."""

import argparse
import pathlib


def c_bytes(data):
    """Format bytes as a C initializer list."""
    return ",".join(f"0x{b:02x}" for b in data)


def defines(source, defs):
    """Header text of `defs` {macro: value}, marked generated by `source`."""
    body = "".join(f"#define {k} {v}\n" for k, v in defs.items())
    return f"/* generated by {source} */\n{body}"


def cli(generate, doc, argv=None, **texts):
    """Write generate(PSID bytes, *texts) to the output path named on the command line. Each
    keyword of `texts` names a text file argument between the PSID and the output, its
    content passed through the keyword's parser."""
    ap = argparse.ArgumentParser(description=doc)
    ap.add_argument("psid")
    for name in texts:
        ap.add_argument(name)
    ap.add_argument("out")
    args = ap.parse_args(argv)
    extra = [
        parse(pathlib.Path(getattr(args, name)).read_text(encoding="ascii"))
        for name, parse in texts.items()
    ]
    text = generate(pathlib.Path(args.psid).read_bytes(), *extra)
    pathlib.Path(args.out).write_text(text, encoding="ascii")
